"""Explicit page-by-page compositions for the documentation atlas.

Every named page receives authored content, controls and hierarchy. Synthetic
examples are never actual identities, fares, authorizations or evidence.
"""
SCREENS={}

def block(kind,title,*items):
    parsed=[]
    for text in items:
        parts=text.split("~")
        parts += [""]*(5-len(parts))
        label,value,control,help_text,options=parts[:5]
        parsed.append(dict(label=label,value=value,type=control or "read-only",help=help_text,
                           options=[x for x in options.split(";") if x]))
    return dict(kind=kind,title=title,items=parsed)

def put(key,layout,title,intro,blocks,primary,secondary="Back",specific=""):
    if key in SCREENS: raise ValueError(key)
    SCREENS[key]=dict(layout=layout,title=title,intro=intro,blocks=blocks,
        actions=[dict(label=primary,role="primary",effect="emit the documented intent only after its current prerequisites hold"),
                 dict(label=secondary,role="secondary",effect="return, dismiss or navigate without changing server facts")],
        specific=specific or "The authored content order and action label must survive the relevant error, recovery and access conditions.")

