put('O87','ops-dialog','Review rollout gate','Record the exact passed/failed evidence decision on an approved or active configuration.',[block('summary','Independent review','Gate~Exact selected criterion','Configuration~Actual version and optimistic revision','Reviewer~Authorized actor distinct from configuration submitter'),block('fields','Decision','Result~Passed~choice~~Passed;Failed','Evidence reference~~text~3–240; non-secret runbook/ticket/test-run/analytics reference; no documents or participant identifiers'),block('notice','Evidence accountability','Owner/review/expiry~Carried by referenced evidence; no invented extra request field')],'Record decision','Cancel','Conflict requires renewed exact-record review; no copied evidence files or locally passed gate. Maker/checker remains enforced by the backend.')

def journey(title="Journey"):
    return block("journey",title,"Pickup~Central square · confirmed map point","Destination~Seafront · confirmed map point")

def vehicle(title="Vehicle"):
    return block("fields",title,"Make~Example manufacturer~text~Required; source max 80 characters", "Model~City sedan~text~Required; max 80", "Year~2021~number~Four digits; existing domain range", "Color~White~text~Required; max 60", "Registration plate~TX 1248~text~Required; max 64", "Taxi identifier~~text~Optional; max 64", "Passenger capacity~4~number~Optional; source 1–12")

def fees():
    return block("money","Recorded economics","Transport fare~35 MAD", "Operator fee~3 MAD", "Expected net~32 MAD~amount~Server record; not calculated by the specimen")

